"""Build a portable browser report from completed saved pilot traces only."""
import json
import os
from pathlib import Path
import tempfile

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'reports/part2/ephemeral_rag_pilot_20261029'


def main():
    results=[]
    with (OUT/'results.jsonl').open() as stream:
        for line in stream:
            if line.endswith('\n'):results.append(json.loads(line))
    if not results:raise ValueError('At least one completed claim required')
    if (OUT/'summary.json').exists():summary=json.loads((OUT/'summary.json').read_text())
    else:
        metrics={}
        for key in ['old_five_sentence','ephemeral_full_article_rag']:
            matrix=[[0]*4 for _ in range(3)];labels=['SUPPORTS','REFUTES','NOT ENOUGH INFO']
            for r in results:
                prediction=r['results'][key]['label'];matrix[labels.index(r['gold'])][labels.index(prediction) if prediction in labels else 3]+=1
            f1=[]
            for i in range(3):
                tp=matrix[i][i];fn=sum(matrix[i])-tp;fp=sum(row[i] for row in matrix)-tp;f1.append(2*tp/(2*tp+fp+fn) if 2*tp+fp+fn else 0.)
            correct=sum(matrix[i][i] for i in range(3));metrics[key]=dict(correct=correct,n=len(results),accuracy=correct/len(results),macro_f1=sum(f1)/3)
        summary=dict(status='running',n=len(results),conditions=metrics,
            fixed=sum(r['results']['old_five_sentence']['label']!=r['gold'] and r['results']['ephemeral_full_article_rag']['label']==r['gold'] for r in results),
            introduced=sum(r['results']['old_five_sentence']['label']==r['gold'] and r['results']['ephemeral_full_article_rag']['label']!=r['gold'] for r in results),
            all_workspaces_deleted=all(r['results']['ephemeral_full_article_rag']['cleanup']['articles_and_database_deleted'] for r in results),
            limitations=json.loads((OUT/'protocol.json').read_text())['limitations'])
    cases=[]
    for row in results:
        cases.append(dict(id=row['id'],claim=row['claim'],gold=row['gold'],
            old=json.loads((OUT/'traces'/('%s_old_five_sentence.json'%row['id'])).read_text()),
            rag=json.loads((OUT/'traces'/('%s_ephemeral_full_article_rag.json'%row['id'])).read_text())))
    data=json.dumps(dict(summary=summary,cases=cases),ensure_ascii=False).replace('<','\\u003c')
    html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FEVER · Temporary RAG pilot</title><style>
:root{--ink:#18364a;--teal:#157c75;--muted:#5d7482;--line:#dbe6ec}*{box-sizing:border-box}body{margin:0;background:#f2f7f9;color:var(--ink);font:14px/1.6 system-ui}main{max-width:1300px;margin:auto;padding:30px 24px}a{color:#176f77}h1{font-size:38px;line-height:1.2;letter-spacing:-1px}h2{font-size:21px}header>p{max-width:90ch;color:var(--muted)}.eyebrow{font-size:11px;letter-spacing:1.3px;color:var(--muted)}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin:25px 0}.stat,.panel{background:white;border:1px solid var(--line);border-radius:12px;padding:20px;margin-bottom:16px}.stat strong{display:block;font-size:33px}.stat small,.small{font-size:11px;color:var(--muted)}.flow{display:flex;gap:7px;flex-wrap:wrap;align-items:center}.flow span{background:#e6f1ee;padding:8px;border-radius:6px;font-size:11px}.notice{background:#fff3de;border-left:3px solid #cf9c48;padding:13px;font-size:12px}.layout{display:grid;grid-template-columns:330px minmax(0,1fr);gap:20px}aside{position:sticky;top:15px;align-self:start}button,select{font:inherit;color:var(--ink);background:white;border:1px solid #bcd0da;border-radius:8px;padding:8px;cursor:pointer}button:focus-visible,select:focus-visible{outline:3px solid #79b9b5;outline-offset:2px}.case{display:block;width:100%;text-align:left;margin:8px 0;padding:12px}.case.active{background:#e2f3ec;border-color:var(--teal);box-shadow:inset 3px 0 var(--teal)}.case strong{display:block;font-size:12px;margin:5px 0}.case small{font-size:10px}.labels{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.label{padding:13px;background:#eef3f6;border-radius:8px;font-size:11px}.label strong{display:block;font-size:16px;margin-top:5px}.correct{background:#e6f4eb}.wrong{background:#fff0e5}.claim{font-size:23px;line-height:1.4}.citation{border-left:3px solid #3a9f82;padding:2px 13px;margin:18px 0}.citation blockquote{margin:7px 0;font-size:14px}.outputs{display:grid;grid-template-columns:1fr 1fr;gap:13px}pre{font:11px/1.6 ui-monospace,monospace;background:#142e42;color:#e6f0f5;padding:14px;border-radius:8px;white-space:pre-wrap;overflow-wrap:anywhere;max-height:440px;overflow:auto}details{border-top:1px solid var(--line);padding:13px 0;margin-top:15px}summary{cursor:pointer;font-size:12px;font-weight:650}.meta{font-size:11px;color:var(--muted);overflow-wrap:anywhere}.gain{color:#167951}.loss{color:#a6512d}select{width:100%;font-size:12px}#count{font-size:11px;color:var(--muted)}.panel{min-width:0}footer{font-size:11px;color:var(--muted);margin-top:25px}@media(max-width:900px){.layout{grid-template-columns:1fr}aside{position:static}#cases{max-height:250px;overflow:auto}.outputs{grid-template-columns:1fr}.stats{gap:8px}.stat{padding:12px}.stat strong{font-size:25px}main{padding:20px 15px}h1{font-size:30px}.labels{grid-template-columns:1fr}.claim{font-size:20px}}
</style></head><body><main><header><a href="/live-llama">← Paused full benchmark</a><p class="eyebrow">COSC 874 · SAVED TEN-CLAIM EXPERIMENT</p><h1>One claim. One temporary knowledge base.</h1><p>Same ten claims and Llama model. Original five-sentence pipeline versus full-article retrieval with local embeddings and precise excerpt citations.</p><div class="flow"><span>Top 5 articles</span>→<span>Fetch & embed</span>→<span>Temporary vector database</span>→<span>Classify & cite</span>→<span>Delete articles + vectors</span></div></header><div id="stats" class="stats"></div><p class="notice">Exploratory pilot: 4 SUPPORTS, 3 REFUTES, 3 NEI. New corpus, retrieval, context and citation prompt change together. These results do not establish a general improvement or isolate a vector-database effect.</p><div class="layout"><aside><h2>Inspect the claims</h2><select id="filter" aria-label="Claim outcome"><option value="all">All ten claims</option><option value="fixed">RAG fixed an error</option><option value="regressed">RAG introduced an error</option><option value="rag-wrong">RAG wrong or invalid</option></select><p id="count"></p><div id="cases"></div></aside><article id="detail"></article></div><section class="panel"><h2>What these results do—and do not—show</h2><div id="limits"></div><p class="small">Original 19K evaluation remains stopped. Full articles and vectors for this pilot were removed per claim. The retained prompt/response and excerpts make each decision inspectable; they are not independent human validation.</p></section><footer>Saved artifacts only. No inference or external model request is triggered by this report. Analysis and viewer added with AI assistance.</footer></main><script id="data" type="application/json">DATA_PLACEHOLDER</script><script>
const D=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);let selected=null;
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined&&text!==null)n.textContent=text;if(cls)n.className=cls;return n;}
function detail(title,value){const d=el('details'),s=el('summary',title);s.setAttribute('aria-label',title);d.append(s,el('pre',typeof value==='string'?value:JSON.stringify(value,null,2)));return d;}
function status(r){return r.rag.label===r.gold?(r.old.label===r.gold?'both-correct':'fixed'):(r.old.label===r.gold?'regressed':'both-wrong');}
function list(){const f=$('filter').value,rows=D.cases.filter(r=>f==='all'||status(r)===f||(f==='rag-wrong'&&r.rag.label!==r.gold));$('count').textContent=rows.length+' matching claims';$('cases').replaceChildren();for(const r of rows){const b=el('button',undefined,'case'+(r.id===selected?' active':''));b.append(el('small','#'+r.id+' · '+status(r)),el('strong',r.claim),el('small',r.old.label+' → '+r.rag.label));b.addEventListener('click',()=>show(r));$('cases').append(b);}if(rows.length&&!rows.some(r=>r.id===selected))show(rows[0]);}
function show(r){selected=r.id;const root=$('detail');root.replaceChildren();const top=el('section',undefined,'panel');top.append(el('span','#'+r.id+' · '+status(r),'eyebrow'),el('h2',r.claim,'claim'));const labels=el('div',undefined,'labels');for(const[name,pred]of [['FEVER reference',r.gold],['Original Llama',r.old.label],['Full-article RAG',r.rag.label]]){const box=el('div',undefined,'label '+(pred===r.gold?'correct':'wrong'));box.append(el('span',name),el('strong',pred));labels.append(box);}top.append(labels,el('p','Temporary articles and vector database deleted: '+r.rag.cleanup.articles_and_database_deleted+' · indexed chunks: '+(r.rag.database?.chunks??'unavailable'),'meta'));if(r.rag.error)top.append(el('p',r.rag.error,'notice'));root.append(top);
const citations=el('section',undefined,'panel');citations.append(el('h2','Precise evidence cited by RAG'));if(!(r.rag.cited_evidence||[]).length)citations.append(el('p','No excerpts cited. NEI may cite none; invalid outputs are counted as errors.','small'));for(const c of r.rag.cited_evidence||[]){const item=el('div',undefined,'citation'),link=el('a',c.title+' · revision '+c.revision_id);if(c.revision_url.startsWith('https://en.wikipedia.org/'))link.href=c.revision_url;item.append(el('b',c.id+' · '+c.section_path.join(' / ')),el('blockquote',c.text),link,el('p',c.block_id+' · character offsets '+c.char_start+'–'+c.char_end,'meta'));citations.append(item);}citations.append(el('p','IDs and quote/source mappings were checked. Whether a citation logically justifies the label still needs evaluation.','small'));root.append(citations);
const outputs=el('section',undefined,'panel');outputs.append(el('h2','What the model actually returned'));const pair=el('div',undefined,'outputs');for(const[name,t]of [['Original',r.old],['RAG',r.rag]]){const col=el('div');col.append(el('b',name),el('pre',t.raw?.response?.message?.content||t.error||'No response'));pair.append(col);}outputs.append(pair);root.append(outputs);
const trace=el('section',undefined,'panel');trace.append(el('h2','Inputs, sources and debug traces'),detail('RAG: exact prompt',r.rag.prompt||'No prompt'),detail('RAG: all supplied excerpts',r.rag.supplied_evidence||{}),detail('RAG: raw HTTP request and response',r.rag.raw||{}),detail('Article metadata and fetch errors',{articles:r.rag.articles,errors:r.rag.fetch_errors}),detail('Vector database and deletion record',{database:r.rag.database,temporary_storage_bytes:r.rag.temporary_storage_bytes,workspace:r.rag.temporary_workspace,cleanup:r.rag.cleanup}),detail('Original: exact prompt and response',{prompt:r.old.prompt,raw:r.old.raw}));const download=el('button','Download both traces ↓');download.addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download='ephemeral-rag-'+r.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});trace.append(download);root.append(trace);history.replaceState(null,'','#'+r.id);document.querySelectorAll('.case').forEach((b,i)=>b.classList.toggle('active',b.textContent.startsWith('#'+r.id+' ·')));}
for(const[key,label]of [['old_five_sentence','Original Llama'],['ephemeral_full_article_rag','Temporary RAG Llama']]){const m=D.summary.conditions[key],box=el('div',undefined,'stat');box.append(el('small',label),el('strong',m.correct+' / '+m.n),el('small',(m.accuracy*100).toFixed(1)+'% accuracy · F1 '+m.macro_f1.toFixed(4)));$('stats').append(box);}const clean=el('div',undefined,'stat');clean.append(el('small','Temporary workspaces deleted'),el('strong',D.summary.all_workspaces_deleted?'10 / 10':'Inspect failures'),el('small',D.summary.fixed+' errors fixed · '+D.summary.introduced+' introduced'));$('stats').append(clean);for(const s of D.summary.limitations)$('limits').append(el('p',s,'small'));$('filter').addEventListener('change',list);const hash=Number(location.hash.slice(1));if(D.cases.some(r=>r.id===hash))selected=hash;list();show(D.cases.find(r=>r.id===selected)||D.cases[0]);
</script></body></html>'''
    html=html.replace("D.summary.all_workspaces_deleted?'10 / 10'","D.summary.all_workspaces_deleted?D.summary.n+' / '+D.summary.n")
    html=html.replace('<h1>One claim. One temporary knowledge base.</h1>','<h1>One claim. One temporary knowledge base.</h1><p id="live-status"></p><button id="refresh-report">Refresh completed claims ↻</button>')
    html=html.replace("for(const[key,label]of", "$('live-status').textContent=D.summary.n+' / 10 paired claims completed · '+(D.summary.status==='complete'?'complete pilot':'partial scores; run continuing');$('refresh-report').addEventListener('click',()=>location.reload());\nfor(const[key,label]of")
    html=html.replace("</script></body>","if(location.protocol!=='file:')setInterval(async()=>{try{const r=await fetch('/api/ephemeral-rag',{cache:'no-store'}),p=await r.json();if(p.progress.completed>D.summary.n)$('live-status').textContent=p.progress.completed+' / 10 completed — refresh to load the new traces.';}catch{}},10000);</script></body>")
    with tempfile.NamedTemporaryFile('w',dir=OUT,prefix='.report-',delete=False) as stream:
        stream.write(html.replace('DATA_PLACEHOLDER',data));temporary=stream.name
    os.replace(temporary,OUT/'index.html')
    print('Built portable pilot report:',OUT/'index.html')

if __name__=='__main__':main()
